%% STEP 2 - Upscale GLDAS-Noah monthly variables from 0.25 to 1 degree
% =========================================================================
% 1. CODE DESCRIPTION
% =========================================================================
% Purpose
%   Aggregate five GLDAS-Noah V2.1 monthly fields to a 1-degree grid using
%   the spherical surface areas of their 0.25-degree source cells.
%
% Input
%   GLDAS_NOAH025_native5_200312_202412.mat, generated by Step 1.
%   Native variables: Prec_mm, Evap_mm, Runoff_mm, SM2m_mm, SurfT_C.
%   Source period: December 2003 to December 2024 (253 months).
%
% Processing
%   Prec_mm, Evap_mm, Runoff_mm and SurfT_C use January 2004 to
%   December 2024 monthly values. Soil-moisture change is calculated
%   before spatial aggregation:
%       dSM2m_mm(t) = SM2m_mm(t) - SM2m_mm(t-1).
%
%   Each 1-degree cell contains 4 x 4 native cells. Valid values are
%   weighted by their spherical surface areas:
%       X_1deg = sum(A_j * X_j) / sum(A_j), over valid native cells.
%   A_j is proportional to sind(lat_j + 0.125) - sind(lat_j - 0.125).
%   The common longitude width and Earth-radius factor cancel in the mean.
%   An output cell is NaN if all its native values are invalid.
%
% Output
%   GLDAS_NOAH10_5vars_200401_202412.mat
%   Prec_mm, Evap_mm, Runoff_mm, dSM2m_mm, SurfT_C: [lat, lon, time]
%   lat, lon: 1-degree grid centers, ascending coordinates
%   Lat2D, Lon2D: geographic coordinate grids
%   ym, yearVec, monthVec: January 2004 to December 2024 (252 months)
%   ValidAreaFraction: valid native-cell area / full 1-degree cell area
%       for each variable and output month (values from 0 to 1)
%   Meta: product information, units and aggregation method
%
%   Units: Prec_mm, Evap_mm, Runoff_mm [mm/month]; dSM2m_mm [mm];
%          SurfT_C [degree C].
%
%   Reference: NASA GES DISC, README_GLDAS2.pdf, Sections 3.3 and 3.5.
%
%% =========================================================================
% 2. CENTRALIZED PARAMETERS
% =========================================================================
clearvars;
clc;

projectRoot = 'D:\P1_SKLGB\M_manuscript1_revised\s1_master_database';
inFile = fullfile(projectRoot, '01_GLDAS_extraction', ...
    'GLDAS_NOAH025_native5_200312_202412.mat');
outFolder = fullfile(projectRoot, '02_spatial_temporal_processing');
outFileName = 'GLDAS_NOAH10_5vars_200401_202412.mat';

% Existing output file: "overwrite" or "stop".
outputMode = "overwrite";

% Period of the resulting monthly fields.
startYear = 2004;
startMonth = 1;
endYear = 2024;
endMonth = 12;

% Number of months read per block from the input MAT-file.
chunkMonths = 12;

makeDiagnosticPlot = true;
plotYM = 200401;

%% =========================================================================
% 3. MAIN EXECUTION
% =========================================================================

%% 3.1 Check paths and parameters
if ~isfile(inFile)
    error('Input MAT-file not found: %s', inFile);
end
if ~ismember(outputMode, ["overwrite", "stop"])
    error('outputMode must be "overwrite" or "stop".');
end
if ~isscalar(chunkMonths) || ~isfinite(chunkMonths) || ...
        chunkMonths < 1 || chunkMonths ~= floor(chunkMonths)
    error('chunkMonths must be a positive integer.');
end
if ~isfolder(outFolder)
    [ok, msg] = mkdir(outFolder);
    if ~ok
        error('Cannot create output directory: %s\n%s', outFolder, msg);
    end
end
outFile = fullfile(outFolder, outFileName);
if isfile(outFile) && outputMode == "stop"
    error('Output MAT-file already exists: %s', outFile);
end

%% 3.2 Read source coordinates and dates
S = matfile(inFile);
Coord = load(inFile, 'lat', 'lon', 'ym');
lat025 = double(Coord.lat(:));
lon025 = double(Coord.lon(:));
ym025 = double(Coord.ym(:));
clear Coord

validateNativeGrid(lat025, lon025);
nLat025 = numel(lat025);
nLon025 = numel(lon025);
nLat1 = nLat025 / 4;
nLon1 = nLon025 / 4;

ym = makeYMList(startYear, startMonth, endYear, endMonth);
nTime = numel(ym);
yearVec = floor(ym / 100);
monthVec = mod(ym, 100);

% The initial December 2003 record is needed for January 2004 dSM2m_mm.
if numel(ym025) ~= nTime + 1 || ym025(1) ~= 200312 || ...
        ~isequal(ym025(2:end), ym)
    error('Input months must run continuously from 2003-12 to 2024-12.');
end
idxMain = (2:nTime+1)';

sourceVars = {'Prec_mm', 'Evap_mm', 'Runoff_mm', 'SM2m_mm', 'SurfT_C'};
expectedInputSize = [nLat025, nLon025, numel(ym025)];
for k = 1:numel(sourceVars)
    sz = size(S, sourceVars{k});
    if ~isequal(sz, expectedInputSize)
        error('Input variable %s has size %s; expected %s.', ...
            sourceVars{k}, mat2str(sz), mat2str(expectedInputSize));
    end
end

fprintf('Input file: %s\n', inFile);
fprintf('Native grid: %d latitude x %d longitude x %d months\n', ...
    nLat025, nLon025, numel(ym025));
fprintf('Output period: %d-%02d to %d-%02d (%d months)\n', ...
    startYear, startMonth, endYear, endMonth, nTime);

%% 3.3 Define the target grid and spherical area weights
lat = mean(reshape(lat025, 4, nLat1), 1)';
lon = mean(reshape(lon025, 4, nLon1), 1)';
[Lon2D, Lat2D] = meshgrid(lon, lat);

% Every source cell spans 0.25 degree in latitude and longitude.
% A common longitude width and radius factor are omitted from the weights.
rowAreaWeight = sind(lat025 + 0.125) - sind(lat025 - 0.125);
if any(~isfinite(rowAreaWeight)) || any(rowAreaWeight <= 0)
    error('Invalid spherical area weights for the native latitude grid.');
end

fprintf('Target grid: %d latitude x %d longitude (1 degree)\n', nLat1, nLon1);
fprintf('Using spherical cell-area weights with available-area normalization.\n');

%% 3.4 Allocate output variables
outputSize = [nLat1, nLon1, nTime];
Prec_mm = NaN(outputSize);
Evap_mm = NaN(outputSize);
Runoff_mm = NaN(outputSize);
dSM2m_mm = NaN(outputSize);
SurfT_C = NaN(outputSize);

% Coverage is stored separately from the five scientific variables.
ValidAreaFraction = struct();
ValidAreaFraction.Prec_mm = NaN(outputSize, 'single');
ValidAreaFraction.Evap_mm = NaN(outputSize, 'single');
ValidAreaFraction.Runoff_mm = NaN(outputSize, 'single');
ValidAreaFraction.dSM2m_mm = NaN(outputSize, 'single');
ValidAreaFraction.SurfT_C = NaN(outputSize, 'single');

%% 3.5 Calculate area-weighted 1-degree monthly fields
runTimer = tic;

fprintf('\nUpscaling Prec_mm...\n');
[Prec_mm, ValidAreaFraction.Prec_mm] = upscaleMatVariable( ...
    S, 'Prec_mm', idxMain, rowAreaWeight, outputSize, chunkMonths);

fprintf('Upscaling Evap_mm...\n');
[Evap_mm, ValidAreaFraction.Evap_mm] = upscaleMatVariable( ...
    S, 'Evap_mm', idxMain, rowAreaWeight, outputSize, chunkMonths);

fprintf('Upscaling Runoff_mm...\n');
[Runoff_mm, ValidAreaFraction.Runoff_mm] = upscaleMatVariable( ...
    S, 'Runoff_mm', idxMain, rowAreaWeight, outputSize, chunkMonths);

fprintf('Calculating dSM2m_mm on the native grid and upscaling...\n');
[dSM2m_mm, ValidAreaFraction.dSM2m_mm] = upscaleSoilChange( ...
    S, idxMain, rowAreaWeight, outputSize, chunkMonths);

fprintf('Upscaling SurfT_C...\n');
[SurfT_C, ValidAreaFraction.SurfT_C] = upscaleMatVariable( ...
    S, 'SurfT_C', idxMain, rowAreaWeight, outputSize, chunkMonths);

fprintf('Upscaling finished in %.2f minutes.\n', toc(runTimer) / 60);

%% 3.6 Check output arrays
checkOutputSize(Prec_mm, outputSize, 'Prec_mm');
checkOutputSize(Evap_mm, outputSize, 'Evap_mm');
checkOutputSize(Runoff_mm, outputSize, 'Runoff_mm');
checkOutputSize(dSM2m_mm, outputSize, 'dSM2m_mm');
checkOutputSize(SurfT_C, outputSize, 'SurfT_C');

fprintf('\nOutput variable summary:\n');
printVarSummary(Prec_mm, ValidAreaFraction.Prec_mm, 'Prec_mm');
printVarSummary(Evap_mm, ValidAreaFraction.Evap_mm, 'Evap_mm');
printVarSummary(Runoff_mm, ValidAreaFraction.Runoff_mm, 'Runoff_mm');
printVarSummary(dSM2m_mm, ValidAreaFraction.dSM2m_mm, 'dSM2m_mm');
printVarSummary(SurfT_C, ValidAreaFraction.SurfT_C, 'SurfT_C');

%% 3.7 Metadata and MAT-file output
Meta = struct();
Meta.sourceProduct = 'GLDAS_NOAH025_M_2.1';
Meta.period = sprintf('%04d-%02d to %04d-%02d', ...
    startYear, startMonth, endYear, endMonth);
Meta.arrayConvention = '[lat, lon, time], ascending latitude and longitude';
Meta.spatialUpscaling = ['4 x 4 native cells per 1-degree cell; ' ...
    'spherical cell-area-weighted mean over finite values'];
Meta.areaWeight = 'sind(lat + 0.125) - sind(lat - 0.125)';
Meta.missingDataRule = 'NaN when no valid source cells; otherwise normalize by valid area';
Meta.ValidAreaFraction = ['Valid source-cell area divided by the full 1-degree ' ...
    'cell area; dSM2m_mm requires valid soil moisture in both months'];
Meta.Prec_mm = 'Rainf_f_tavg * 86400 * days_in_month; mm/month';
Meta.Evap_mm = 'Evap_tavg * 86400 * days_in_month; mm/month';
Meta.Runoff_mm = '(Qs_acc + Qsb_acc) * 8 * days_in_month; mm/month';
Meta.dSM2m_mm = 'SM2m_mm(t) - SM2m_mm(t-1), then area-weighted; mm';
Meta.SurfT_C = 'AvgSurfT_inst - 273.15; degree C';
Meta.sourceDOI = '10.5067/SXAVCZFAQLNO';

fprintf('\nSaving MAT-file: %s\n', outFile);
save(outFile, ...
    'Prec_mm', 'Evap_mm', 'Runoff_mm', 'dSM2m_mm', 'SurfT_C', ...
    'lat', 'lon', 'Lat2D', 'Lon2D', ...
    'ym', 'yearVec', 'monthVec', 'ValidAreaFraction', 'Meta', '-v7.3');
fprintf('Saved successfully.\n');

%% 3.8 Diagnostic map
if makeDiagnosticPlot
    plotIndex = find(ym == plotYM, 1);
    if isempty(plotIndex)
        warning('Plot month %06d is outside the output period.', plotYM);
    else
        rainMap = Prec_mm(:, :, plotIndex);
        figure('Name', 'GLDAS-Noah 1-degree precipitation');
        h = imagesc(lon, lat, rainMap);
        set(h, 'AlphaData', double(isfinite(rainMap)));
        set(gca, 'YDir', 'normal');
        axis equal tight;
        box on;
        grid on;
        colormap(jet);
        cb = colorbar;
        ylabel(cb, 'Precipitation (mm/month)');
        title(sprintf('GLDAS-Noah precipitation, %04d-%02d, 1 degree', ...
            floor(plotYM / 100), mod(plotYM, 100)));
        xlabel('Longitude');
        ylabel('Latitude');
        set(gca, 'FontName', 'Times New Roman', 'FontSize', 11);
    end
end

%% =========================================================================
% 4. LOCAL FUNCTIONS
% =========================================================================

function ym = makeYMList(y1, m1, y2, m2)
    d1 = datetime(y1, m1, 1);
    d2 = datetime(y2, m2, 1);
    if d2 < d1
        error('End month must not precede start month.');
    end
    d = d1:calmonths(1):d2;
    ym = double(year(d(:)) * 100 + month(d(:)));
end

function validateNativeGrid(lat025, lon025)
    if numel(lat025) ~= 600 || numel(lon025) ~= 1440 || ...
            any(~isfinite(lat025)) || any(~isfinite(lon025))
        error('Input must contain the full GLDAS 600 x 1440 native grid.');
    end
    tol = 1e-5;
    if any(abs(diff(lat025) - 0.25) > tol) || ...
            any(abs(diff(lon025) - 0.25) > tol) || ...
            abs(lat025(1) + 59.875) > tol || ...
            abs(lat025(end) - 89.875) > tol || ...
            abs(lon025(1) + 179.875) > tol || ...
            abs(lon025(end) - 179.875) > tol
        error('Input coordinates are not aligned to the GLDAS 0.25-degree grid.');
    end
end

function [Y, C] = upscaleMatVariable(S, varName, idxMain, wLat, outSize, chunkMonths)
    Y = NaN(outSize);
    C = NaN(outSize, 'single');
    nTime = numel(idxMain);
    for t1 = 1:chunkMonths:nTime
        t2 = min(t1 + chunkMonths - 1, nTime);
        X = double(S.(varName)(:, :, idxMain(t1:t2)));
        [Yblock, Cblock] = areaWeighted025to1(X, wLat);
        Y(:, :, t1:t2) = Yblock;
        C(:, :, t1:t2) = Cblock;
    end
end

function [Y, C] = upscaleSoilChange(S, idxMain, wLat, outSize, chunkMonths)
    Y = NaN(outSize);
    C = NaN(outSize, 'single');
    nTime = numel(idxMain);
    for t1 = 1:chunkMonths:nTime
        t2 = min(t1 + chunkMonths - 1, nTime);
        % The first and last soil-moisture records span one extra month.
        SM = double(S.SM2m_mm(:, :, (idxMain(t1)-1):idxMain(t2)));
        dSM = diff(SM, 1, 3);
        [Yblock, Cblock] = areaWeighted025to1(dSM, wLat);
        Y(:, :, t1:t2) = Yblock;
        C(:, :, t1:t2) = Cblock;
    end
end

function [Y, C] = areaWeighted025to1(X, wLat)
    % Input: [lat025, lon025, time]. Output: [lat1, lon1, time].
    [nLat025, nLon025, nTime] = size(X);
    if mod(nLat025, 4) ~= 0 || mod(nLon025, 4) ~= 0 || ...
            numel(wLat) ~= nLat025
        error('Incompatible source dimensions or area weights.');
    end
    nLat1 = nLat025 / 4;
    nLon1 = nLon025 / 4;

    % Reshape into [4 native latitudes, 1-degree latitudes,
    % 4 native longitudes, 1-degree longitudes, months].
    X = reshape(X, 4, nLat1, 4, nLon1, nTime);
    w = reshape(wLat, 4, nLat1, 1, 1, 1);
    valid = isfinite(X);
    X(~valid) = 0;

    weightedSum = sum(sum(X .* w, 1), 3);
    validWeight = sum(sum(double(valid) .* w, 1), 3);
    numerator = reshape(weightedSum, nLat1, nLon1, nTime);
    denominator = reshape(validWeight, nLat1, nLon1, nTime);

    Y = numerator ./ denominator;
    Y(denominator == 0) = NaN;

    totalWeight = 4 * sum(reshape(wLat, 4, nLat1), 1);
    C = single(denominator ./ reshape(totalWeight, nLat1, 1, 1));
    C = max(0, min(1, C));
end

function checkOutputSize(X, expectedSize, varName)
    if ~isequal(size(X), expectedSize) || ~isa(X, 'double')
        error('Unexpected size or data type for %s.', varName);
    end
end

function printVarSummary(X, C, varName)
    nFinite = nnz(isfinite(X));
    nPartial = nnz(C(:) > 0 & C(:) < 1 - 1e-6);
    fprintf(['%-10s | valid: %7.2f%% | partial-area cells: %8d | ' ...
        'min: %10.4f | mean: %10.4f | max: %10.4f\n'], ...
        varName, 100 * nFinite / numel(X), nPartial, ...
        min(X(:), [], 'omitnan'), mean(X(:), 'omitnan'), ...
        max(X(:), [], 'omitnan'));
end
